def main():
 manifest=json.loads((ROOT/'manifest.json').read_text());assert manifest['state']=='FROZEN_VALIDATED';queue=json.loads((ROOT/'global_queue_status.json').read_text());assert queue['status']=='complete' and queue['audited']==12 and not queue['failures'];accept=json.loads((ROOT/'acceptance.json').read_text());summary=json.loads((ROOT/'analyses/summary.json').read_text());rows=json.loads((ROOT/'analyses/per_instance.json').read_text());bounds=[];recovery=[]
 for eid in manifest['global_preregistered']:
  r=ROOT/'global_bounds_parallel'/eid
