 methods=[]
 for method in ('mass','risk','greedy','risk_exchange','mass_exchange','greedy_exchange'):
  gains=[1-r[method]/min(r['mass'],r['risk']) for r in rows];methods.append(dict(method=method,**stats(gains),positive=sum(g>1e-8 for g in gains),negative=sum(g<-1e-8 for g in gains)))
